def _merged(below: dict, override: dict, prefix: str) -> dict:
    out = dict(below)
    for key, value in override.items():
        path = prefix + str(key)
        if key not in below:
            raise KeyError(f"unknown config key {path!r}")
        if isinstance(below[key], dict) and isinstance(value, dict):
            out[key] = _merged(below[key], value, path + ".")
        else:
            out[key] = copy.deepcopy(value)
    return out

